// HU5 — ganador determinístico: lee el archivo, filtra mi gid, gana la 1ra línea; junta los N file_id y limpia
const fsm = require('fs');
const BUF = 'C:/Users/Nico/AppData/Local/Temp/postly_carrusel_buffer.tsv';
const myFileId = String($('HU5: Buffer grupo').first().json.file_id);
const gid = String($('HU5: Buffer grupo').first().json.gid);
let lines = [];
try { lines = fsm.readFileSync(BUF, 'utf8').split('\n').filter(Boolean); } catch (e) {}
const mine = lines.map(l => l.split('\t')).filter(p => p[0] === gid);
