const ten = fileIds.slice(0, 10);
const chatId = mine[0][2];
const rest = lines.filter(l => l.split('\t')[0] !== gid); // limpiar las líneas de este grupo
try { fsm.writeFileSync(BUF, rest.length ? rest.join('\n') + '\n' : '', 'utf8'); } catch (e) {}
return ten.map((fid, i) => ({ json: { file_id: fid, idx: i, chatId, gid, total: ten.length } }));

