// HU5 — analiza compliance+orden en una sola pasada de Gemini
const raw = ($('HU5: Analizar carrusel').first().json.content.parts[0].text) || '';
let p = { tiene_precio: false, detalle: '', orden: [], preview: '' };
try { p = JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim()); } catch (e) {}
const juntar = $('HU5: Juntar URLs').first().json;
