  return [{ json: { tiene_precio: true, detalle: p.detalle || '', chatId: juntar.chatId, gid: juntar.gid } }];
}
let orden = Array.isArray(p.orden) ? p.orden.map(Number).filter(n => Number.isInteger(n) && n >= 1 && n <= images.length).map(n => n - 1) : [];
const seen = new Set(orden);
for (let i = 0; i < images.length; i++) if (!seen.has(i)) { orden.push(i); seen.add(i); }
orden = orden.slice(0, images.length);
const orderedUrls = orden.map(i => images[i].url);
const lineas = orden.map((o, pos) => `${pos + 1}. imagen #${o + 1}`).join('\n');
const mensaje = `🖼️ Recibí tu carrusel de ${images.length} imágenes.\n\n*Orden narrativo propuesto:*\n${lineas}\n\n_${p.preview || 'Secuencia optimizada para retención.'}_\n\n¿Lo usamos así o preferís tu orden original?`;
const store = $getWorkflowStaticData('global');
store['carousel_' + juntar.gid] = { aiUrls: orderedUrls, origUrls: images.map(im => im.url), total: images.length, chatId: juntar.chatId };
return [{ json: { tiene_precio: false, chatId: juntar.chatId, gid: juntar.gid, total: images.length, mensaje } }];

const crypto = require('crypto');
const KEY = Buffer.from($env.POSTLY_ENC_KEY, 'hex');
function decrypt(val) {
  if (!val || typeof val !== 'string' || !val.startsWith('enc:')) return val;
  const raw = Buffer.from(val.slice(4), 'base64');
  const iv = raw.subarray(0, 12), tag = raw.subarray(12, 28), ct = raw.subarray(28);
  const d = crypto.createDecipheriv('aes-256-gcm', KEY, iv); d.setAuthTag(tag);
  return Buffer.concat([d.update(ct), d.final()]).toString('utf8');
}
return $input.all().map(item => ({ json: { ...item.json, AccessToken: decrypt(item.json.AccessToken) } }));

// HU5 2b — arma el caption final (HU7 precios + HU9 firma) y recupera urls del set
