for (let i = 0; i < items.length; i++) {
  // Vamos a buscar el archivo binario al disco duro de n8n
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // Lo transformamos a texto Base64
  items[i].json.fotoBase64 = buffer.toString('base64');
