// HU9 — Compliance Sentinel: bloqueo de precios (HU7) + firma legal desde Config (BD central)
const items = $('Resolucion - IG').all();
const result = [];

// Firma/contacto desde la pestaña Config (BD central). Fallback a la línea legal histórica.
const FIRMA_FALLBACK = "-- Consultora de Belleza Independiente Mary Kay --";
// Config = pestaña con columnas (firma | contacto) y una fila de datos. Headers case-insensitive.
let cfg = {};
try {
  const row = (($('Leer Config').first() || {}).json) || {};
  for (const h of Object.keys(row)) cfg[h.trim().toLowerCase()] = String(row[h] ?? '').trim();
} catch (e) { /* Config ausente -> fallback */ }

const firmaLinea = cfg.firma || FIRMA_FALLBACK;
const contacto   = cfg.contacto || '';

// Patrones prohibidos por Mary Kay (HU7 - detección de precios en texto)
const patronesPrecios = [
  /\$\s?\d+/g,                    // $1500, $ 1500
  /\d+[\.,]\d{3}/g,               // 1.500, 1,500
  /\d+%\s?(off|desc)/gi,          // 50% off, 50% desc
  /\b(oferta|promocion|promo|descuento|rebaja|barato|economico|gratis)\b/gi
];

for (const item of items) {
  let caption = item.json.Caption_IG || '';
  let precioDetectado = false;
